(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.BasicLimitLesson,num=window.LinearLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function fmt(x){return String(Number(x.toFixed(4))).replace('.','{,}');}
const expressions={polynomial:String.raw`x^2+1`,factor:String.raw`\frac{x^2-4}{x-2}`,radical:String.raw`\frac{\sqrt{x+2}-2}{x-2}`,absolute:String.raw`\frac{|x-2|}{x-2}`},reasons={polynomial:'Polinomial dapat disubstitusi langsung. Nilai pada masukan dua adalah lima.',factor:'Pembilang adalah selisih dua kuadrat. Faktorkan untuk menemukan faktor yang sama pada pembilang dan penyebut.',radical:'Selisih akar dapat dikalikan bentuk sekawan untuk menghasilkan faktor x dikurangi dua.',absolute:'Nilai mutlak memberi aturan berbeda di kiri dan kanan dua. Periksa kedua sisi sebelum menyimpulkan limit.'},explanations={polynomial:[String.raw`\lim_{x\to2}(x^2+1)=2^2+1=5`],factor:[String.raw`\frac{x^2-4}{x-2}=\frac{(x-2)(x+2)}{x-2}=x+2\quad(x\ne2)`,String.raw`\lim_{x\to2}(x+2)=4`],radical:[String.raw`\frac{\sqrt{x+2}-2}{x-2}=\frac1{\sqrt{x+2}+2}\quad(x\ne2)`,String.raw`\lim_{x\to2}\frac1{\sqrt{x+2}+2}=\frac14`],absolute:[String.raw`\lim_{x\to2^-}\frac{|x-2|}{x-2}=-1`,String.raw`\lim_{x\to2^+}\frac{|x-2|}{x-2}=1`,String.raw`\text{Kedua limit berbeda; limit dua sisi tidak ada.}`]};let previousKind='';
function draw(){const kind=$('#method-kind').value,index=Number($('#method-step').value),d=core.distances[index],t=core.approach(kind,d),config=core.cases[kind];$('#distance-output').value=String(d).replace('.',',');$('#method-step').setAttribute('aria-valuetext',String(d));math($('#method-problem'),String.raw`\lim_{x\to2}`+' '+expressions[kind]);$('#substitution-note').textContent=kind==='polynomial'?'Substitusi awal memberi dua kuadrat ditambah satu, yaitu lima.':'Substitusi awal membuat pembilang dan penyebut sama-sama nol. Ini bentuk tak tentu; belum merupakan nilai limit.';if(previousKind!==kind){$('#method-choice').value='';$('#method-feedback').textContent='';$('#method-feedback').className='feedback';$('#method-explanation').open=false;$('#explanation-content').replaceChildren();const p=document.createElement('p');p.textContent=reasons[kind];$('#explanation-content').append(p);for(const tex of explanations[kind]){const box=document.createElement('div');box.className='formula';math(box,tex);$('#explanation-content').append(box);}previousKind=kind;}let grid='';for(let x=0;x<=4;x++){const p=core.point(kind,x,0);grid+=`<line x1="${p.x}" x2="${p.x}" y1="30" y2="310" class="${x===0?'wave-axis':'wave-grid-line'}"/><text x="${p.x}" y="332" text-anchor="middle" class="wave-grid-label">${x}</text>`;}for(const y of config.ticks){const p=core.point(kind,0,y);grid+=`<line x1="50" x2="610" y1="${p.y}" y2="${p.y}" class="${y===0?'wave-axis':'wave-grid-line'}"/><text x="42" y="${p.y+5}" text-anchor="end" class="wave-grid-label">${String(y).replace('.',',')}</text>`;}$('#method-grid').innerHTML=grid;for(const side of ['left','right'])$('#method-'+side+'-curve').setAttribute('d',core.curve(kind,side).map((p,i)=>`${i?'L':'M'}${p.x} ${p.y}`).join(' '));for(const [id,x,y]of [['method-left-point',t.leftX,t.leftY],['method-right-point',t.rightX,t.rightY]]){const p=core.point(kind,x,y);$('#'+id).setAttribute('cx',p.x);$('#'+id).setAttribute('cy',p.y);}const special=kind==='absolute'?[-1,1]:[config.limit];$('#method-special').innerHTML=special.map(y=>{const p=core.point(kind,2,y);return `<circle cx="${p.x}" cy="${p.y}" r="5" class="${kind==='polynomial'?'method-filled':'method-hole'}"/>`;}).join('');$('#method-table').innerHTML=core.distances.map((distance,i)=>{const v=core.approach(kind,distance);return `<tr ${i===index?'class="method-selected"':''}>${[distance,v.leftX,v.leftY,v.rightX,v.rightY].map(n=>`<td><span data-tex="${fmt(n)}"></span></td>`).join('')}</tr>`;}).join('');math($('#method-values'),String.raw`\begin{aligned}f(${fmt(t.leftX)})&\approx${fmt(t.leftY)}\\f(${fmt(t.rightX)})&\approx${fmt(t.rightY)}\\f(2)&`+(t.at===null?String.raw`\text{ tidak terdefinisi}`:'='+fmt(t.at))+String.raw`\end{aligned}`);$('#method-note').textContent=(t.limit===null?'Nilai dari kiri negatif satu dan dari kanan satu. Limit dua sisi tidak ada.':`Keluaran dari kedua sisi mendekati ${kind==='polynomial'?'lima':kind==='factor'?'empat':'seperempat'}. `+(t.at===null?'Fungsi awal tetap tidak terdefinisi pada masukan dua.':'Nilai fungsi di titik sama dengan limitnya.'))+' Tabel dibulatkan hingga empat angka di belakang koma. Buka alasan penyelesaian untuk membaca dasar aljabarnya; tabel saja belum membuktikan limit.';$('#method-plot').setAttribute('aria-label',`Contoh ${kind==='polynomial'?'polinomial':kind==='factor'?'faktorisasi':kind==='radical'?'bentuk sekawan':'nilai mutlak'}. Jarak masukan dari dua ${d}. Kiri: (${t.leftX.toFixed(4)}, ${t.leftY.toFixed(4)}). Kanan: (${t.rightX.toFixed(4)}, ${t.rightY.toFixed(4)}). Nilai tepat di dua ${t.at===null?'tidak terdefinisi':t.at}. Limit dua sisi ${t.limit===null?'tidak ada':t.limit}.`);}
$('#method-kind').addEventListener('input',draw);$('#method-step').addEventListener('input',draw);$('#check-method').addEventListener('click',()=>{const kind=$('#method-kind').value,choice=$('#method-choice').value,ok=choice===core.cases[kind].strategy;$('#method-feedback').className='feedback '+(choice?(ok?'correct':'incorrect'):'');$('#method-feedback').textContent=!choice?'Pilih langkah dahulu.':(ok?'Tepat. ':'Belum sesuai. ')+reasons[kind];});draw();
const questions=[{tex:String.raw`\lim_{x\to2}(x^2+1)`,prompt:'Berapa nilai limit ini?',n:5,d:1,hint:'Polinomial dapat disubstitusi langsung.',why:'Dua kuadrat ditambah satu sama dengan lima.'},{tex:String.raw`\lim_{x\to3}\frac{x^2-9}{x-3}`,prompt:'Berapa nilai limit ini?',n:6,d:1,hint:'Faktorkan pembilang menjadi x dikurangi tiga dikali x ditambah tiga.',why:'Di sekitar tiga tetapi bukan tepat tiga, pecahan sama dengan x ditambah tiga. Limitnya enam.'},{tex:String.raw`\lim_{x\to4}\frac{\sqrt{x+5}-3}{x-4}`,prompt:'Berapa nilai limit ini?',n:1,d:6,hint:'Kalikan pembilang dan penyebut dengan akar x ditambah lima, ditambah tiga.',why:'Setelah memakai sekawan, bentuknya satu dibagi akar x ditambah lima ditambah tiga. Limit penyebutnya enam, sehingga hasilnya seperenam.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n,q.d));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis nilai limit sebagai bilangan atau pecahan, misalnya 6 atau 1/6.':'Belum tepat. Periksa hasil substitusi dan penyederhanaan aljabar yang sah.');}));
const choices=[{tex:String.raw`\lim_{x\to2}\frac{|x-2|}{x-2}`,prompt:'Apa kesimpulan yang benar?',options:[{text:'Limitnya nol karena substitusi memberi nol dibagi nol.'},{text:'Limit dua sisi tidak ada; hasil kiri dan kanan berbeda.'},{text:'Limitnya satu karena faktor yang sama dapat selalu dicoret.'}],answer:1,why:'Di kiri dua, pecahan bernilai negatif satu. Di kanan dua, pecahan bernilai satu. Kedua limit satu sisi tidak sama.'},{tex:String.raw`\frac{(x-2)(x+2)}{x-2}=x+2`,prompt:'Apa syarat penyederhanaan ini pada fungsi awal?',options:[{tex:String.raw`x\ne2`,label:'x bukan dua'},{text:'Berlaku di semua bilangan real tanpa syarat.'},{tex:String.raw`x\ne-2`,label:'x bukan negatif dua'}],answer:0,why:'Faktor yang dibatalkan adalah x dikurangi dua. Pembatalan memerlukan faktor tersebut bukan nol, sehingga nilai fungsi awal di dua tetap tidak terdefinisi.'},{tex:String.raw`\text{Substitusi menghasilkan bentuk }0/0`,prompt:'Apa yang dapat disimpulkan pada tahap ini?',options:[{text:'Limitnya pasti nol.'},{text:'Limitnya pasti tidak ada.'},{text:'Hasil limit belum ditentukan; perlu alasan lebih lanjut.'}],answer:2,why:'Bentuk nol dibagi nol tidak menentukan hasil. Faktorisasi, sekawan, atau pemeriksaan satu sisi dapat mengungkap limit yang berbeda untuk fungsi berbeda.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}" ${o.label?'aria-label="'+o.label+'"':''}>${o.tex?'<span data-tex="'+o.tex+'"></span>':o.text}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-basic-limits-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-basic-limits-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();